sksl:
#version 300
uniform shader image;
uniform float2 size;
uniform float2 layer;
uniform float3x3 fromLayer;
uniform float3x3 toLayer;
uniform float4 screen;
uniform float time;
float2 amzCoord;
float4 amzOutput;
float2 amzScreenNorm() { float2 p=amzCoord-screen.xy; return float2(p.x/screen.z,1.0-p.y/screen.w); }
float2 amzLayerNorm() { float3 p=toLayer*float3(amzCoord,1.0); float2 n=p.xy/p.z/layer; return float2(n.x,1.0-n.y); }
float2 amzLayerCenter() { float3 p=fromLayer*float3(layer*.5,1.0); return p.xy/p.z-screen.xy; }
float4x4 amzRowMatrix(float3x3 m) { return float4x4(m[0].x,m[1].x,0.0,m[2].x, m[0].y,m[1].y,0.0,m[2].y, 0.0,0.0,1.0,0.0, m[0].z,m[1].z,0.0,m[2].z); }
float4x4 amzLayerToScreen() {
    float3x3 toNorm=float3x3(1.0/screen.z,0.0,0.0, 0.0,-1.0/screen.w,0.0,-screen.x/screen.z,1.0+screen.y/screen.w,1.0);
    float3x3 toPixels=float3x3(layer.x,0.0,0.0, 0.0,-layer.y,0.0, 0.0,layer.y,1.0);
    return amzRowMatrix(toNorm*fromLayer*toPixels);
}
float4x4 amzScreenToLayer() {
    float3x3 toPixels=float3x3(screen.z,0.0,0.0, 0.0,-screen.w,0.0, screen.x,screen.y+screen.w,1.0);
    float3x3 toNorm=float3x3(1.0/layer.x,0.0,0.0, 0.0,-1.0/layer.y,0.0,0.0,1.0,1.0);
    return amzRowMatrix(toNorm*toLayer*toPixels);
}
float2 getTexSize(float2 v) { return v; }
int amzIntMax(int a,int b) { return int(max(float(a),float(b))); }
int amzIntMin(int a,int b) { return int(min(float(a),float(b))); }
int amzIntAbs(int a) { return int(abs(float(a))); }
int amzIntClamp(int a,int b,int c) { return int(clamp(float(a),float(b),float(c))); }
const int amzPass=0;
uniform float amzIteration;
float4 amzSample_inputImg(float2 uv) { return float4(image.eval((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/1.0)); }
float4 amzTexture(int tex,float2 uv) { if(tex==0) return amzSample_inputImg(uv);return float4(0.0); }
uniform float amzp_autop;
uniform float amzp_autoSpeed;
uniform float amzp_scale;
uniform float amzp_angle;
uniform float2 amzp_position;
uniform float2 amzp_stretch;
uniform float amzp_alpha;
uniform float amzp_hardness;
uniform float amzp_blendMode;
uniform float amzp_alphaComp;
uniform float amzp_evolution;
uniform float amzp_shape;
uniform float amzp_density;
uniform float amzp_size;
uniform float amzp_sizeVar;
uniform float amzp_softness;
uniform float amzp_rim;
uniform float amzp_fringe;
uniform float amzp_twinkle;
uniform float amzp_driftAngle;
uniform float amzp_brightness;
uniform float amzp_palette;
layout(color) uniform half4 amzp_color1;
layout(color) uniform half4 amzp_color2;
uniform float amzp_seed;
uniform float amzp_gradMap;
uniform float amzp_gmTri;
layout(color) uniform half4 amzp_gmFg;
layout(color) uniform half4 amzp_gmMid;
layout(color) uniform half4 amzp_gmBg;
uniform float amzp_overdrawOn;
    float2 nmRot(float2 q, float a) { float c = cos(a), s = sin(a); return float2(c * q.x - s * q.y, s * q.x + c * q.y); }
    float2 nmStd(float2 p, float pxs) {
        float z = max(amzp_scale * 2.0, 0.002);
        p -= amzp_position * pxs;
        p = nmRot(p, -radians(amzp_angle));
        return p / (z * max(amzp_stretch, float2(0.01)));
    }
    float2 nmStdInv(float2 q, float pxs) {
        float z = max(amzp_scale * 2.0, 0.002);
        return nmRot(q * z * max(amzp_stretch, float2(0.01)), radians(amzp_angle)) + amzp_position * pxs;
    }
    float4 nmGradMap(float4 fx) {
        if (!(amzp_gradMap>0.5)) return fx;
        float3 un = fx.a > 0.0001 ? fx.rgb / fx.a : float3(0.0);
        float v = clamp(fx.a * (0.25 + 0.75 * dot(un, float3(0.299, 0.587, 0.114))), 0.0, 1.0);
        float4 pB = float4(amzp_gmBg.rgb * amzp_gmBg.a, amzp_gmBg.a), pM = float4(amzp_gmMid.rgb * amzp_gmMid.a, amzp_gmMid.a), pF = float4(amzp_gmFg.rgb * amzp_gmFg.a, amzp_gmFg.a);
        float4 c = (amzp_gmTri>0.5) ? (v < 0.5 ? mix(pB, pM, v * 2.0) : mix(pM, pF, v * 2.0 - 1.0)) : mix(pB, pF, v);
        return c;
    }
    float4 nmBlend(float4 tex, float4 fx) {
        float4 f = clamp(fx * amzp_hardness, 0.0, 1.0) * clamp(amzp_alpha, 0.0, 1.0);
        float4 b = tex * clamp(amzp_alphaComp, 0.0, 1.0);
        float4 o;
        if (int(amzp_blendMode) == 0) o = f;
        else if (int(amzp_blendMode) == 1) o = float4(b.rgb * (f.rgb + (1.0 - f.a)), b.a);
        else if (int(amzp_blendMode) == 2) o = float4(b.rgb + f.rgb - b.rgb * f.rgb, b.a + f.a - b.a * f.a);
        else if (int(amzp_blendMode) == 4) o = float4(b.rgb + f.rgb, max(b.a, f.a));
        else o = f + b * (1.0 - f.a);
        o = clamp(o, 0.0, 1.0);
        return float4(min(o.rgb, float3(o.a)), o.a);
    }
    float4 nmLight(float3 L) { L = max(L, 0.0); return float4(clamp(L, 0.0, 1.0), clamp(max(L.r, max(L.g, L.b)), 0.0, 1.0)); }
    float prog(float p) { return (amzp_autop>0.5) ? p + time * (amzp_autoSpeed * 0.2) : p; }
    float2 l2s(float2 v) { return (float4(v, 0.0, 1.0) * amzLayerToScreen()).xy; }
    bool inside(float2 uv) { return uv.x >= 0.0 && uv.x <= 1.0 && uv.y >= 0.0 && uv.y <= 1.0; }
    float4 layerAt(float2 uv) { return inside(uv) ? amzTexture(0, l2s(uv)) : float4(0.0); }
    float3 hue(float h) { return clamp(abs(mod(h * 6.0 + float3(0.0, 4.0, 2.0), 6.0) - 3.0) - 1.0, 0.0, 1.0); }
    float h1(float2 p, float k) { return fract(sin(dot(p, float2(127.1, 311.7)) + k * 17.31 + amzp_seed * 3.917) * 43758.5453); }
    float shapeD(float2 q) {
        if (int(amzp_shape) == 1 || int(amzp_shape) == 2) {
            float nside = int(amzp_shape) == 1 ? 6.0 : 8.0;
            float a = atan(q.y, q.x);
            float seg = 6.2831853 / nside;
            float k = cos(seg * 0.5) / cos(mod(a + seg * 0.5, seg) - seg * 0.5);
            return length(q) / k;
        } else if (int(amzp_shape) == 3) {
            float2 h = q * float2(1.0, 1.15) + float2(0.0, 0.25);
            float a = h.x * h.x + h.y * h.y - 0.55;
            return clamp(1.0 + (a * a * a - h.x * h.x * h.y * h.y * h.y) * 4.0, 0.0, 3.0) * 0.5 + length(q) * 0.5;
        }
        return length(q);
    }
    float disk(float2 q, float soft, float rimK) {
        float d = shapeD(q);
        float body = 1.0 - smoothstep(1.0 - soft, 1.0, d);
        float ring = exp(-pow((d - (1.0 - soft * 0.5)) / (0.06 + soft * 0.15), 2.0)) * rimK;
        return body * (0.55 + 0.45 * (1.0 - d * d * 0.5)) + ring * body;
    }
    void amzRender() {
        float2 W = layer;
        float pxs = screen.zw.x / max(screen.zw.x, 1.0);
        float2 p = (amzLayerNorm() - 0.5) * W;
        float2 q0 = nmStd(float2(p.x, -p.y), pxs);
        q0.y = -q0.y;
        float4 orig = layerAt(amzLayerNorm());
        float t = prog(amzp_evolution);
        float2 drift = float2(cos(radians(amzp_driftAngle)), -sin(radians(amzp_driftAngle)));
        float3 L = float3(0.0);
        float soft = clamp(amzp_softness, 0.0, 1.0) * 0.9 + 0.04;
        for (int amzLocal_layer = 0; amzLocal_layer < 3; amzLocal_layer++) {
            float fl = float(amzLocal_layer);
            float depth = 0.45 + fl * 0.45;
            float cell = max(amzp_size * pxs, 2.0) * 2.4 * depth;
            float2 D = drift * t * cell * (0.6 + fl * 0.5) - float2(fl * 37.1, fl * 11.7) * cell;
            float2 q = q0 + D;
            float2 g = floor(q / cell);
            for (int j = -1; j <= 1; j++) {
                for (int i = -1; i <= 1; i++) {
                    float2 c = g + float2(float(i), float(j));
                    float kk = fl * 5.0;
                    if (h1(c, kk + 1.0) > clamp(amzp_density, 0.0, 1.0)) continue;
                    float2 amzLocal_pos = (c + float2(h1(c, kk + 2.0), h1(c, kk + 3.0))) * cell;
                    amzLocal_pos += float2(sin(t * 1.3 + h1(c, kk + 4.0) * 6.28), cos(t * 1.1 + h1(c, kk + 5.0) * 6.28)) * cell * 0.08;
                    float rad = max(amzp_size * pxs, 2.0) * depth * mix(1.0, 0.35 + 1.3 * h1(c, kk + 6.0), clamp(amzp_sizeVar, 0.0, 1.0));
                    float2 dq = (q - amzLocal_pos) / rad;
                    if (dot(dq, dq) > 4.0) continue;
                    float tw = 1.0 - clamp(amzp_twinkle, 0.0, 1.0) * (0.5 + 0.5 * sin(t * 4.0 + h1(c, kk + 7.0) * 31.0));
                    float inten = (0.35 + 0.65 * h1(c, kk + 8.0)) * tw * (0.55 + fl * 0.25);
                    float3 col;
                    float hv = h1(c, kk + 9.0);
                    if (int(amzp_palette) == 0) col = mix(float3(1.0, 0.72, 0.35), float3(1.0, 0.45, 0.3), hv);
                    else if (int(amzp_palette) == 1) col = mix(float3(0.35, 0.75, 1.0), float3(0.6, 0.45, 1.0), hv);
                    else if (int(amzp_palette) == 2) col = hue(hv) * 0.8 + 0.2;
                    else if (int(amzp_palette) == 3) col = mix(amzp_color1.rgb, amzp_color2.rgb, hv);
                    else {
                        float2 lq = amzLocal_pos - D;
                        lq = nmStdInv(float2(lq.x, -lq.y), pxs);
                        float2 luv = float2(lq.x, -lq.y) / W + 0.5;
                        float4 lc = layerAt(clamp(luv, 0.0, 1.0));
                        col = lc.a > 0.001 ? lc.rgb / lc.a : float3(1.0);
                        col = mix(col, float3(1.0), 0.15);
                    }
                    float fr = clamp(amzp_fringe, 0.0, 1.0) * 0.12;
                    float3 v = float3(disk(dq * (1.0 + fr), soft, amzp_rim), disk(dq, soft, amzp_rim), disk(dq * (1.0 - fr), soft, amzp_rim));
                    L += v * col * inten;
                }
            }
        }
        amzOutput = nmBlend(orig, nmGradMap(nmLight(L * max(amzp_brightness, 0.0))));
      if (!(amzp_overdrawOn>0.5)) amzOutput *= amzTexture(0, amzScreenNorm()).a;
    }

half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }
